INSERT INTO `attempt_feedbacks` (
  `id`, `attempt_id`, `failure_reason`, `risk_alert`, `next_mission`,
  `model_version`, `prompt_version`, `generated_at`, `created_at`, `updated_at`
) VALUES
  (9401, 9301, '시작 동작에서 왼팔로 먼저 당겨 골반이 벽에서 빨리 떨어졌습니다.', '첫 동작에서 어깨 부담이 크게 올라갑니다.', '오른발을 먼저 올린 뒤 손을 뻗어보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-03 19:06:00', '2026-03-03 19:06:00', '2026-03-03 19:06:00'),
  (9402, 9302, '손보다 발이 늦게 들어와 중심이 흔들렸습니다.', '계속 팔로 먼저 당기면 어깨 피로가 빨리 쌓입니다.', '손보다 발 위치를 먼저 확인해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-05 19:13:00', '2026-03-05 19:13:00', '2026-03-05 19:13:00'),
  (9403, 9303, '코어는 좋아졌지만 상단 발 동작이 아직 짧았습니다.', '발 교체가 늦으면 다시 스윙이 생길 수 있습니다.', '손을 뻗기 전에 골반을 한 박자 고정해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-08 19:21:00', '2026-03-08 19:21:00', '2026-03-08 19:21:00'),
  (9404, 9304, '중간 구간은 안정적이었지만 마무리 동작이 급했습니다.', '허리가 열리면 마지막 동작 거리가 길어집니다.', '마지막 손 동작 전 오른발로 먼저 일어서보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-12 19:29:00', '2026-03-12 19:29:00', '2026-03-12 19:29:00'),
  (9405, 9305, '움직임 동선이 정리되며 크럭스 시간이 줄었습니다.', '상단에서 작은 스윙이 아직 남아 있습니다.', '마무리 구간에서 가슴을 벽에 더 가깝게 유지해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-16 19:37:00', '2026-03-16 19:37:00', '2026-03-16 19:37:00'),
  (9406, 9306, '체중 이동이 안정적으로 이어지며 완등 동작이 깔끔했습니다.', '마지막 빠져나오는 동작에서 왼팔 의존이 조금 남아 있습니다.', '같은 리듬으로 다음 색도 도전해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-21 19:51:00', '2026-03-21 19:51:00', '2026-03-21 19:51:00'),
  (9407, 9307, '시작 자세는 좋아졌지만 첫 크로스에서 아직 팔 힘을 많이 씁니다.', '초반 어깨 부담이 다시 올라오는 패턴입니다.', '손보다 발로 먼저 동작을 만들어보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-24 18:23:00', '2026-03-24 18:23:00', '2026-03-24 18:23:00'),
  (9408, 9308, '코어는 유지됐지만 크럭스 발 전환이 늦었습니다.', '오른발이 늦게 들어오면 몸이 다시 바깥으로 밀립니다.', '교차 동작 전 발에 잠깐 멈춰보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-26 18:35:00', '2026-03-26 18:35:00', '2026-03-26 18:35:00'),
  (9409, 9309, '동선은 짧아졌지만 마무리 홀드를 너무 급하게 처리했습니다.', '상단에서 빨라지면 다시 스윙이 생길 수 있습니다.', '마지막 두 동작을 천천히 연결해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-28 18:48:00', '2026-03-28 18:48:00', '2026-03-28 18:48:00'),
  (9410, 9311, '오른발이 밀어주기 전에 손 동작이 먼저 나왔습니다.', '무릎이 안쪽으로 무너지며 균형이 깨집니다.', '오른다리로 먼저 밀어낸 뒤 손을 써보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-02 18:36:00', '2026-03-02 18:36:00', '2026-03-02 18:36:00'),
  (9411, 9312, '발 위치는 좋아졌지만 크럭스에서 하체 힘이 아직 약합니다.', '지지 시간이 짧아지면 미끄러질 수 있습니다.', '오른발에 한 박자 더 실어보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-06 18:45:00', '2026-03-06 18:45:00', '2026-03-06 18:45:00'),
  (9412, 9313, '동선 파악이 좋아지며 크럭스 구간이 짧아졌습니다.', '범프 동작에서 몸통이 아직 열립니다.', '갈비뼈 방향을 벽 쪽으로 유지해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-09 18:57:00', '2026-03-09 18:57:00', '2026-03-09 18:57:00'),
  (9413, 9314, '하체 타이밍은 좋아졌지만 마무리에서 여전히 팔 의존이 있습니다.', '후반으로 갈수록 팔 부담이 다시 올라갑니다.', '마지막은 당기지 말고 일어서서 마무리해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-13 19:09:00', '2026-03-13 19:09:00', '2026-03-13 19:09:00'),
  (9414, 9315, '이제는 하체 드라이브가 동작을 끌고 갑니다.', '발끝 압력이 빨리 풀리면 다시 균형이 흔들릴 수 있습니다.', '상단 발에는 끝까지 힘을 남겨보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-17 19:17:00', '2026-03-17 19:17:00', '2026-03-17 19:17:00'),
  (9415, 9316, '하체 리듬이 전체 구간에 유지되며 완등이 깔끔했습니다.', '크럭스 이후 타이밍만 조금 더 정교해지면 좋습니다.', '같은 발 리듬으로 한 단계 더 올라가보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-20 19:23:00', '2026-03-20 19:23:00', '2026-03-20 19:23:00'),
  (9416, 9317, '초반은 차분해졌지만 발 전환이 아직 늦습니다.', '늦은 발 전환은 무릎 부담을 키웁니다.', '발을 먼저 두고 골반을 가운데에 유지해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-24 19:19:00', '2026-03-24 19:19:00', '2026-03-24 19:19:00'),
  (9417, 9318, '중심은 좋아졌지만 크럭스 회전이 아직 덜 끝났습니다.', '골반이 너무 빨리 열리면 손 동작 거리가 길어집니다.', '발이 완전히 서고 나서 골반을 돌려보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-26 19:37:00', '2026-03-26 19:37:00', '2026-03-26 19:37:00'),
  (9418, 9319, '완등에 가까워졌지만 마지막 일어서는 동작이 아직 망설여집니다.', '세 번째 동작에서 피로가 다시 보입니다.', '발을 믿고 더 길게 일어서보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-28 20:03:00', '2026-03-28 20:03:00', '2026-03-28 20:03:00'),
  (9419, 9321, '몸이 올라오기 전에 오른팔이 먼저 힘을 많이 받았습니다.', '크럭스 전 팔 부담이 커서 낙하 위험도 올라갑니다.', '골반부터 열고 올라가보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-01 20:06:00', '2026-03-01 20:06:00', '2026-03-01 20:06:00'),
  (9420, 9322, '중간 구간은 길어졌지만 후반 지구력이 아직 떨어집니다.', '호흡이 짧아지면 팔 부담이 다시 급격히 올라갑니다.', '크럭스 전에 한 번 호흡을 정리해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-04 20:19:00', '2026-03-04 20:19:00', '2026-03-04 20:19:00'),
  (9421, 9323, '접촉 안정성은 좋아졌지만 마무리에서 아직 멈칫합니다.', '긴 락오프가 에너지를 많이 씁니다.', '발에서 더 빨리 다음 동작을 열어보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-08 20:27:00', '2026-03-08 20:27:00', '2026-03-08 20:27:00'),
  (9422, 9324, '페이스 조절이 좋아지며 크럭스 구간이 짧아졌습니다.', '시선이 늦으면 가슴이 다시 벽에서 떨어질 수 있습니다.', '다음 홀드를 눈으로 먼저 찾고 손을 보내보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-12 20:35:00', '2026-03-12 20:35:00', '2026-03-12 20:35:00'),
  (9423, 9325, '지구력이 더 오래 유지되며 몸도 벽에 가까워졌습니다.', '마지막 손 교체에서 팔 긴장이 아직 큽니다.', '안정된 발마다 그립 힘을 잠깐 풀어보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-18 20:43:00', '2026-03-18 20:43:00', '2026-03-18 20:43:00'),
  (9424, 9326, '완등 시도에서는 페이스와 바디 텐션이 훨씬 안정적이었습니다.', '상단에서 그립을 세게 쥐는 습관은 조금 남아 있습니다.', '같은 호흡 리듬으로 더 어려운 문제를 가보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-21 20:51:00', '2026-03-21 20:51:00', '2026-03-21 20:51:00'),
  (9425, 9327, '골반 위치는 좋아졌지만 첫 락이 아직 너무 빠릅니다.', '초반 당기기 패턴이 다시 어깨에 부담을 줍니다.', '발을 먼저 세우고 몸을 올린 뒤 락을 걸어보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-23 19:29:00', '2026-03-23 19:29:00', '2026-03-23 19:29:00'),
  (9426, 9328, '몸은 더 가까워졌지만 크럭스 발 동작이 아직 확실하지 않습니다.', '발 확신이 없으면 작은 스윙이 계속 생깁니다.', '손 교체 전에 발을 먼저 강하게 실어보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-25 19:42:00', '2026-03-25 19:42:00', '2026-03-25 19:42:00'),
  (9427, 9329, '전체 동선은 매끄러워졌지만 상단 타이밍은 아직 준비가 덜 됐습니다.', '마무리를 급하게 처리하면 골반이 다시 열릴 수 있습니다.', '끝까지 골반 라인을 유지해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-28 19:54:00', '2026-03-28 19:54:00', '2026-03-28 19:54:00'),
  (9428, 9331, '다이나믹 동작이 나오기 전에 골반이 몸 아래로 들어오지 못했습니다.', '골반이 열리면 발이 떨어질 수 있습니다.', '점프 전에 왼쪽 골반을 더 안으로 넣어보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-03 17:46:00', '2026-03-03 17:46:00', '2026-03-03 17:46:00'),
  (9429, 9332, '타이밍은 좋아졌지만 착지 발이 늦었습니다.', '발이 늦게 붙으면 상체 보정이 커집니다.', '손이 붙는 순간 발도 바로 맞춰보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-07 17:59:00', '2026-03-07 17:59:00', '2026-03-07 17:59:00'),
  (9430, 9333, '동작 연결은 짧아졌지만 중간 스윙이 아직 남아 있습니다.', '크로스 구간에서 다시 흔들릴 위험이 있습니다.', '잡은 뒤 한 박자 멈춰보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-10 18:07:00', '2026-03-10 18:07:00', '2026-03-10 18:07:00'),
  (9431, 9334, '코어가 더 개입하면서 전체 동작이 덜 튀게 변했습니다.', '마무리를 급하게 하면 몸이 다시 열릴 수 있습니다.', '시작보다 마무리 제어에 더 집중해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-14 18:13:00', '2026-03-14 18:13:00', '2026-03-14 18:13:00'),
  (9432, 9335, '다이나믹 구간이 이제는 꽤 안정적으로 유지됩니다.', '마지막 스텝에서 작은 균형 손실은 남아 있습니다.', '같은 리듬으로 다음 챌린지에도 적용해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-18 18:20:00', '2026-03-18 18:20:00', '2026-03-18 18:20:00'),
  (9433, 9336, '마지막 시도에서는 다이나믹 구간과 마무리가 깔끔하게 이어졌습니다.', '피곤한 시도에서는 골반이 조금씩 다시 열릴 수 있습니다.', '이제는 한 단계 더 어려운 다이나믹 문제를 가보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-21 18:23:00', '2026-03-21 18:23:00', '2026-03-21 18:23:00'),
  (9434, 9337, '초반 점프는 좋아졌지만 착지 안정성이 아직 낮습니다.', '불안정한 착지는 손목과 발목 부담을 키웁니다.', '착지 후 발을 바로 세워보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-24 18:56:00', '2026-03-24 18:56:00', '2026-03-24 18:56:00'),
  (9435, 9338, '캐치 타이밍은 좋아졌지만 빠져나오는 발이 아직 몸을 따라갑니다.', '빠져나오는 발이 늦으면 다시 스윙이 생깁니다.', '출구 발을 더 빨리 두어보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-26 19:13:00', '2026-03-26 19:13:00', '2026-03-26 19:13:00'),
  (9436, 9339, '다이나믹 구간 제어 시간이 더 길어졌습니다.', '상단에서 작은 스윙은 아직 남아 있습니다.', '잡고 나서 바로 움직이지 말고 한 박자 버텨보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-28 19:27:00', '2026-03-28 19:27:00', '2026-03-28 19:27:00'),
  (9437, 9341, '어려운 문제라 시작부터 왼팔로 많이 당기며 몸이 주저앉았습니다.', '팔 부담과 크럭스 시간이 모두 높아 피로 위험이 큽니다.', '시작 발 셋업에 1초 더 써보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-01 14:06:00', '2026-03-01 14:06:00', '2026-03-01 14:06:00'),
  (9438, 9342, '바디 라인은 조금 나아졌지만 크럭스를 여전히 벽에서 멀리 시작합니다.', '반복된 어깨 사용으로 파워가 빨리 빠집니다.', '두 번째 동작에서 가슴을 더 붙여보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-04 14:19:00', '2026-03-04 14:19:00', '2026-03-04 14:19:00'),
  (9439, 9343, '발은 더 쓰고 있지만 손이 여전히 일을 많이 하고 있습니다.', '긴 락오프 시간이 아직 선명합니다.', '당기기 전에 다리로 먼저 밀어보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-06 14:33:00', '2026-03-06 14:33:00', '2026-03-06 14:33:00'),
  (9440, 9344, '중간 홀드까지는 왔지만 크럭스 이후 회복이 느립니다.', '회복이 느리면 다음 동작 리듬이 끊깁니다.', '범프 이후 긴장을 조금 풀어보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-10 14:47:00', '2026-03-10 14:47:00', '2026-03-10 14:47:00'),
  (9441, 9345, '전체 시퀀스가 점점 짧고 깔끔해지고 있습니다.', '오른쪽 라인에 아직 힘이 많이 남아 있습니다.', '발 쪽으로 체중 이동을 더 빨리 해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-13 15:03:00', '2026-03-13 15:03:00', '2026-03-13 15:03:00'),
  (9442, 9346, '이제는 코어가 어려운 구간을 제대로 받쳐줍니다.', '상단에서 망설이면 에너지가 다시 크게 빠집니다.', '탑 발은 더 빠르게 확정해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-17 15:15:00', '2026-03-17 15:15:00', '2026-03-17 15:15:00'),
  (9443, 9347, '거의 다 왔고 마지막 빠져나오기만 아직 불안정합니다.', '허리 드리프트가 다시 생기면 미끄러질 수 있습니다.', '골반을 붙인 채 발끝으로 끝까지 밀어보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-21 15:29:00', '2026-03-21 15:29:00', '2026-03-21 15:29:00'),
  (9444, 9348, '이 완등은 한 달 성장 흐름이 가장 잘 보입니다. 크럭스는 짧아지고 균형은 좋아졌으며 위험 동작은 크게 줄었습니다.', '크럭스 이후 그립을 세게 쥐는 습관은 조금 남아 있습니다.', '이 시도의 리듬을 기준 영상처럼 활용해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-23 15:51:00', '2026-03-23 15:51:00', '2026-03-23 15:51:00'),
  (9445, 9349, '새 문제에서는 시작이 좋아졌지만 중간 어려운 구간에서 다시 팔 의존이 보입니다.', '오른팔 부담이 새 문제에서 다시 올라갑니다.', '새 문제도 발 기반으로 다시 시퀀스를 만들어보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-26 19:21:00', '2026-03-26 19:21:00', '2026-03-26 19:21:00'),
  (9446, 9350, '첫 시도보다 전체 흐름은 이미 더 부드러워졌습니다.', '상단 타이밍은 아직 불안정합니다.', '같은 텐션을 유지하면서 마지막 일어서기만 천천히 해보세요.', 'demo-model-v1', 'demo-prompt-v1', '2026-03-28 20:19:00', '2026-03-28 20:19:00', '2026-03-28 20:19:00');

