INSERT INTO `challenge_summaries` (
  `id`, `challenge_id`, `average_center_stability_ratio`, `most_crux_hold_no`,
  `max_crux_duration_ms`, `final_comment`, `created_at`, `updated_at`
) VALUES
  (9601, 9201, 0.60, 7, 3600, '이 계정은 주차별 성장 흐름이 가장 안정적으로 보입니다. 중심 안정성과 하체 타이밍이 여섯 번의 시도 동안 꾸준히 좋아졌습니다.', '2026-03-21 20:05:00', '2026-03-21 20:05:00'),
  (9602, 9203, 0.57, 5, 3800, '핵심 변화는 오른다리 드라이브입니다. 3월 후반 시도에서는 손보다 발이 먼저 만드는 움직임이 확실히 보입니다.', '2026-03-20 19:22:00', '2026-03-20 19:22:00'),
  (9603, 9205, 0.56, 7, 4100, '이 계정은 지구력과 페이스 개선을 보여주기 좋습니다. 팔 과부하가 줄고 완등 시도에서는 훨씬 차분해졌습니다.', '2026-03-21 20:50:00', '2026-03-21 20:50:00'),
  (9604, 9207, 0.59, 9, 3500, '다이나믹 문제 제어력이 눈에 띄게 좋아졌습니다. 후반 시도일수록 착지 안정성과 스윙 억제가 좋아집니다.', '2026-03-21 18:22:00', '2026-03-21 18:22:00'),
  (9605, 9209, 0.52, 6, 4700, '이 계정이 발표용 핵심입니다. 한 달 가까이 같은 어려운 챌린지를 반복하며 1회차와 8회차의 차이가 극적으로 드러납니다.', '2026-03-23 15:50:00', '2026-03-23 15:50:00');

